// One item per search term, so each gets its own API call downstream.
const cfg = $('Search Criteria').first().json;
const cvText = $('CV to text').first().json.cvText;

return cfg.searchTerms.map(term => ({
  json: {
    term,
    location: cfg.location,
    salaryFloor: cfg.salaryFloor,
    salaryTarget: cfg.salaryTarget,
    cvText,
  }
}));

// Both APIs return different shapes. Everything downstream depends on one
// schema, so normalise here and nowhere else.
const out = [];
const seen = new Set();

for (const item of $input.all()) {
  const d = item.json;

  // Reed
  for (const r of (d.results ?? [])) {
    if (r.jobId === undefined) continue;
    const id = `reed-${r.jobId}`;
    if (seen.has(id)) continue;
    seen.add(id);
    out.push({ json: {
      externalId: id,
      source: 'Reed',
      title: r.jobTitle,
      company: r.employerName,
      location: r.locationName,
      url: r.jobUrl,
      description: (r.jobDescription ?? '').replace(/<[^>]*>/g, '').slice(0, 2000),
      salaryMin: r.minimumSalary ?? null,
      salaryMax: r.maximumSalary ?? null,
      postedAt: r.date ?? null,
    }});
  }

  // Adzuna
  for (const a of (d.results ?? [])) {
    if (a.id === undefined || a.jobId !== undefined) continue;
    const id = `adzuna-${a.id}`;
    if (seen.has(id)) continue;
    seen.add(id);
    out.push({ json: {
      externalId: id,
      source: 'Adzuna',
      title: a.title,
      company: a.company?.display_name ?? 'Unknown',
      location: a.location?.display_name ?? '',
      url: a.redirect_url,
      description: (a.description ?? '').replace(/<[^>]*>/g, '').slice(0, 2000),
      salaryMin: a.salary_min ?? null,
      salaryMax: a.salary_max ?? null,
      postedAt: a.created ?? null,
    }});
  }
}

return out;

// The dedupe step. Anything already in Notion is dropped here, which is why
// the daily digest only ever contains genuinely new postings.
const existing = new Set();
for (const page of ($input.first().json.results ?? [])) {
  const idProp = page.properties?.['External ID'];
  const val = idProp?.rich_text?.[0]?.plain_text;
  if (val) existing.add(val);
}

const jobs = $('Normalise to one schema').all()
  .map(i => i.json)
  .filter(j => !existing.has(j.externalId));

if (jobs.length === 0) return [];
return jobs.map(json => ({ json }));

// Batch the jobs into one prompt rather than one call per job: cheaper, and
// the model can rank consistently when it sees them together.
const jobs = $input.all().map(i => i.json);
const cvText = $('CV to text').first().json.cvText;
const cfg = $('Search Criteria').first().json;

const summaries = jobs.map((j, i) => `[${i}] ${j.title} at ${j.company} (${j.location})
Salary: ${j.salaryMin ?? '?'} - ${j.salaryMax ?? '?'}
${j.description.slice(0, 800)}`).join('

---

');

const prompt = `Here is a CV:

${cvText}

The candidate wants roles matching: ${cfg.searchTerms.join(', ')}. Salaries above ${cfg.salaryTarget} are strongly preferred; ${cfg.salaryFloor}-${cfg.salaryTarget} is acceptable but less attractive.

Score each job below from 0-100 for fit against the CV and criteria. Consider seniority, domain overlap, and whether the CV's experience genuinely qualifies them.

${summaries}

Return ONLY a JSON array, no prose, of the form:
[{"index": 0, "score": 87, "reason": "one sentence"}]`;

return [{ json: { prompt, jobCount: jobs.length } }];

// Attach scores back onto the jobs, apply the salary banding, sort best first.
const jobs = $('Drop jobs already stored').all().map(i => i.json);
const cfg = $('Search Criteria').first().json;
const raw = $input.first().json?.content?.[0]?.text ?? '[]';

let scores = [];
try {
  const match = raw.match(/\[[\s\S]*\]/);
  scores = match ? JSON.parse(match[0]) : [];
} catch (e) {
  // A malformed model response must not lose the jobs - fall back to unscored.
  scores = [];
}

const byIndex = new Map(scores.map(s => [s.index, s]));

const scored = jobs.map((j, i) => {
  const s = byIndex.get(i);
  const top = j.salaryMax ?? j.salaryMin ?? 0;
  let band = 'Unknown';
  if (top >= cfg.salaryTarget) band = 'Target (100k+)';
  else if (top >= cfg.salaryFloor) band = 'Viable (80-100k)';
  else if (top > 0) band = 'Below floor';

  // Salary band nudges the ranking but never replaces fit - a perfect role at
  // 95k should still outrank a poor one at 120k.
  const bandBonus = band === 'Target (100k+)' ? 5 : 0;

  return {
    ...j,
    score: Math.min(100, (s?.score ?? 0) + bandBonus),
    reason: s?.reason ?? 'Not scored',
    salaryBand: band,
  };
});

scored.sort((a, b) => b.score - a.score);
return scored.map(json => ({ json }));

// Build the digest from the ranked list, not from the Notion write results,
// so a Notion hiccup still gets you the email.
const jobs = $('Rank and band').all().map(i => i.json);
if (jobs.length === 0) return [];

const row = j => `<tr>
  <td style="padding:8px;border-bottom:1px solid #eee"><b>${j.score}</b></td>
  <td style="padding:8px;border-bottom:1px solid #eee"><a href="${j.url}">${j.title}</a><br><small>${j.company} - ${j.location}</small></td>
  <td style="padding:8px;border-bottom:1px solid #eee">${j.salaryBand}<br><small>${j.salaryMin ?? '?'} - ${j.salaryMax ?? '?'}</small></td>
  <td style="padding:8px;border-bottom:1px solid #eee"><small>${j.reason}</small></td>
</tr>`;

const html = `<h2>${jobs.length} new role${jobs.length === 1 ? '' : 's'} today</h2>
<table style="border-collapse:collapse;font-family:sans-serif;font-size:14px">
<tr><th align="left">Score</th><th align="left">Role</th><th align="left">Salary</th><th align="left">Why</th></tr>
${jobs.map(row).join('')}
</table>`;

return [{ json: { html, count: jobs.length } }];
